import os
from urllib.parse import urlparse
from pydantic import BaseModel, Field, HttpUrl
from firecrawl import FirecrawlApp

ALLOWED_DOMAINS = {"docs.partner-erp.vn", "pricing.vendor-demo.vn"}

class PricingTier(BaseModel):
    plan_name: str = Field(..., min_length=2)
    monthly_vnd: int = Field(..., ge=0)
    quota_note: str

class CompetitorPricingPayload(BaseModel):
    source_url: HttpUrl
    effective_quarter: str
    tiers: list[PricingTier]

def assert_safe_target(raw_url: str) -> str:
    parsed = urlparse(raw_url)
    if parsed.scheme != "https" or parsed.hostname not in ALLOWED_DOMAINS:
        raise ValueError(f"Blocked non-allowlisted crawl target: {raw_url}")
    return raw_url

def fetch_clean_catalog_for_rag(target_url: str) -> dict:
    safe_url = assert_safe_target(target_url)

    # Dùng MIT SDK giao tiếp qua HTTP boundary tới Cloud hoặc container OSS nguyên bản trong VPC
    app = FirecrawlApp(
        api_key=os.environ.get("FIRECRAWL_API_KEY", "fc-internal-vpc-token"),
        api_url=os.environ.get("FIRECRAWL_BASE_URL", "https://api.firecrawl.dev"),
    )

    response = app.scrape_url(
        safe_url,
        params={
            "formats": ["markdown", "extract"],
            "onlyMainContent": True,
            "excludeTags": ["nav", "footer", "aside", "script"],
            "extract": {
                "schema": CompetitorPricingPayload.model_json_schema(),
                "prompt": "Trích xuất chính xác bảng giá và hạn mức từng gói bằng tiếng Việt, không tự suy diễn con số."
            },
        },
    )

    structured = CompetitorPricingPayload.model_validate({
        **response.get("extract", {}),
        "source_url": safe_url,
    })

    markdown_body = response.get("markdown", "").strip()
    if len(markdown_body) < 120:
        raise RuntimeError("Empty or bot-blocked response; skip RAG upsert.")

    return {
        "source_url": str(structured.source_url),
        "structured_pricing": structured.model_dump(),
        "rag_markdown": markdown_body,
    }
